const res = await fetch("https://api.basile.cc/people/find", {
  method: "POST",
  headers: { Authorization: BASILE_KEY, "Content-Type": "application/json" },
  body: JSON.stringify({ countOnly: true, filters: {
    result_role: { include: ["CEO", "PDG"] },
    result_country_code: { include: ["FR"] },
    hide_legal_entities: true } }),
});
console.log((await res.json()).total);
